/* @lc app=leetcode id=1959 lang=kotlin */ class Solution { fun minSpaceWastedKResizing(nums: IntArray, k: Int): Int = nums.size.let { n -> nums.runningFold(0) { s, x -> s + x }.let { pre -> Array(n + 1) { p -> nums.drop(p).runningFold(0) { m, x -> maxOf(m, x) }.let { mx -> IntArray(n + 1) { i -> if (i <= p) 0 else mx[i - p] * (i - p) - (pre[i] - pre[p]) } } }.let { w -> (1..k + 1).runningFold(IntArray(n + 1) { if (it == 0) 0 else Int.MAX_VALUE / 2 }) { dp, _ -> IntArray(n + 1) { i -> if (i == 0) Int.MAX_VALUE / 2 else (0 until i).minOf { p -> dp[p] + w[p][i] } } }.minOf { it[n] } } } } }